head.script:
scwin.__iframeShowNormal = function() {
    var iframe = WebSquare.wUnit.getJq("body iframe");
    return iframe.contents().find("body").length == 4;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("assert", "scwin.__iframeShowNormal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    iframe2.setSrc("iFrame_src_SKT-728_(WSQ-2479)_sub(XML).xml");
    iframe4.setSrc("iFrame_src_SKT-728_(WSQ-2479)_sub(HTML).html");
    //Function unitTest
    //Created By: Sang.do
    //Created By: 19-Mar-2018
    //end unitTest
}
